package cue

import (
	_ "embed"
	"errors"
	"fmt"
	"strings"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
	yamlv3 "gopkg.in/yaml.v3"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type Result struct {
	Errors []Error `json:"errors"`
}

// Unwrap returns the individual errors carried by a multi-error.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if errors.As(err, &multi) {
		return multi.Unwrap(), true
	}
	return nil, false
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks a YAML document's shape and references.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return err
	}

	var issues []error
	for _, e := range cueerrors.Errors(v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))) {
		issue := Error{Message: e.Error(), Location: Location{File: file, Line: 1, Column: 1}}
		if positions := cueerrors.Positions(e); len(positions) > 0 {
			p := positions[len(positions)-1]
			if p.Line() > 0 && p.Column() > 0 {
				issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
			}
		}
		issues = append(issues, issue)
	}
	// Check references independently so all missing keys can be reported together.
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return err
	}
	if len(root.Content) > 0 {
		issues = append(issues, referenceErrors(file, root.Content[0])...)
	}
	if len(issues) == 0 {
		return nil
	}
	return validationErrors(issues)
}

type validationErrors []error

func (e validationErrors) Error() string {
	messages := make([]string, 0, len(e))
	for _, issue := range e {
		messages = append(messages, issue.Error())
	}
	return strings.Join(messages, "\n")
}
func (e validationErrors) Unwrap() []error      { return []error(e) }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

func field(n *yamlv3.Node, key string) *yamlv3.Node {
	if n == nil || n.Kind != yamlv3.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}
func items(n *yamlv3.Node) []*yamlv3.Node {
	if n != nil && n.Kind == yamlv3.SequenceNode {
		return n.Content
	}
	return nil
}
func value(n *yamlv3.Node) string {
	if n != nil {
		return n.Value
	}
	return ""
}

func referenceErrors(file string, root *yamlv3.Node) []error {
	var issues []error
	namespace := value(field(root, "namespace"))
	if namespace == "" {
		namespace = "default"
	}
	segments := map[string]bool{}
	for _, s := range items(field(root, "segments")) {
		segments[value(field(s, "key"))] = true
	}
	add := func(flag string, index int, kind string, n *yamlv3.Node) {
		if n == nil || n.Kind != yamlv3.ScalarNode || n.Value == "" {
			return
		}
		issues = append(issues, Error{
			Message:  fmt.Sprintf("flag %s/%s rule %d references unknown %s %q", namespace, flag, index, kind, n.Value),
			Location: Location{File: file, Line: n.Line, Column: n.Column},
		})
	}
	for _, f := range items(field(root, "flags")) {
		flag := value(field(f, "key"))
		variants := map[string]bool{}
		for _, variant := range items(field(f, "variants")) {
			variants[value(field(variant, "key"))] = true
		}
		for i, rule := range items(field(f, "rules")) {
			segment := field(rule, "segment")
			if segment != nil && segment.Kind == yamlv3.MappingNode {
				for _, key := range items(field(segment, "keys")) {
					if !segments[key.Value] {
						add(flag, i+1, "segment", key)
					}
				}
			} else if segment != nil && !segments[segment.Value] {
				add(flag, i+1, "segment", segment)
			}
			for _, dist := range items(field(rule, "distributions")) {
				variant := field(dist, "variant")
				if variant != nil && !variants[variant.Value] {
					add(flag, i+1, "variant", variant)
				}
			}
		}
	}
	return issues
}

// ValidateReferences checks rule references without applying the CUE schema.
// Import uses this before writing any resources.
func ValidateReferences(file string, b []byte) error {
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return err
	}
	if len(root.Content) == 0 {
		return nil
	}
	issues := referenceErrors(file, root.Content[0])
	if len(issues) == 0 {
		return nil
	}
	return validationErrors(issues)
}
