package cue

import (
	"fmt"
	"os"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestValidateValidFixtures(t *testing.T) {
	validator, err := NewFeaturesValidator()
	require.NoError(t, err)
	for _, file := range []string{"testdata/valid_v1.yaml", "testdata/valid.yaml", "testdata/valid_segments_v2.yaml"} {
		t.Run(file, func(t *testing.T) {
			data, err := os.ReadFile(file)
			require.NoError(t, err)
			assert.NoError(t, validator.Validate(file, data))
		})
	}
}

func TestValidateFailure(t *testing.T) {
	data, err := os.ReadFile("testdata/invalid.yaml")
	require.NoError(t, err)
	validator, err := NewFeaturesValidator()
	require.NoError(t, err)
	issues, ok := Unwrap(validator.Validate("testdata/invalid.yaml", data))
	require.True(t, ok)
	require.NotEmpty(t, issues)
	assert.Equal(t, "flags.0.rules.1.distributions.0.rollout: invalid value 110 (out of bound <=100) (testdata/invalid.yaml 22:17)", issues[0].Error())
}

func TestValidateReferences(t *testing.T) {
	data := []byte("namespace: demo\nflags:\n- key: flag\n  name: Flag\n  variants: []\n  rules:\n  - segment: absent\n    distributions:\n    - variant: missing\n      rollout: 100\nsegments: []\n")
	validator, err := NewFeaturesValidator()
	require.NoError(t, err)
	issues, ok := Unwrap(validator.Validate("example.yaml", data))
	require.True(t, ok)
	require.Len(t, issues, 2)
	assert.EqualError(t, issues[0], "flag demo/flag rule 1 references unknown segment \"absent\" (example.yaml 7:14)")
	assert.EqualError(t, issues[1], "flag demo/flag rule 1 references unknown variant \"missing\" (example.yaml 9:16)")
}

func TestValidateBooleanRuleSegment(t *testing.T) {
	data := []byte("flags:\n- key: enabled\n  name: Enabled\n  type: BOOLEAN_FLAG_TYPE\n  variants: []\n  rules:\n  - segment:\n      keys: [known, absent]\n    distributions: []\nsegments:\n- key: known\n  name: Known\n  match_type: ALL_MATCH_TYPE\n")
	validator, err := NewFeaturesValidator()
	require.NoError(t, err)
	issues, ok := Unwrap(validator.Validate("boolean.yaml", data))
	require.True(t, ok)
	assert.Contains(t, fmt.Sprint(issues), "flag default/enabled rule 1 references unknown segment \"absent\"")
}
